// Draws the original "Millennium Chrome" skin bitmaps for bit.cheer.
// Every pixel here is generated by this script; no third-party skin art is used.
// Run: node scripts/make-millennium-skin.mjs
import { writeFileSync, mkdirSync } from 'node:fs';
import { deflateSync } from 'node:zlib';

const OUT = new URL('../public/skins/millennium/', import.meta.url);
mkdirSync(OUT, { recursive: true });

// ---------- tiny RGBA canvas + PNG encoder ----------
function canvas(w, h) {
  const px = new Uint8ClampedArray(w * h * 4);
  const hex = (c) => typeof c === 'string'
    ? [parseInt(c.slice(1, 3), 16), parseInt(c.slice(3, 5), 16), parseInt(c.slice(5, 7), 16), c.length > 7 ? parseInt(c.slice(7, 9), 16) : 255]
    : c;
  const set = (x, y, color) => {
    if (x < 0 || y < 0 || x >= w || y >= h) return;
    const [r, g, b, a] = hex(color), i = (y * w + x) * 4, sa = a / 255, da = px[i + 3] / 255;
    const oa = sa + da * (1 - sa);
    if (!oa) return;
    px[i] = (r * sa + px[i] * da * (1 - sa)) / oa;
    px[i + 1] = (g * sa + px[i + 1] * da * (1 - sa)) / oa;
    px[i + 2] = (b * sa + px[i + 2] * da * (1 - sa)) / oa;
    px[i + 3] = oa * 255;
  };
  const rect = (x, y, rw, rh, color) => { for (let j = y; j < y + rh; j++) for (let i = x; i < x + rw; i++) set(i, j, color); };
  const clear = (x, y) => px.fill(0, (y * w + x) * 4, (y * w + x) * 4 + 4);
  return { w, h, px, set, rect, clear };
}

const CRC = new Uint32Array(256).map((_, n) => { let c = n; for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1; return c >>> 0; });
const crc32 = (buf) => { let c = 0xffffffff; for (const b of buf) c = CRC[(c ^ b) & 0xff] ^ (c >>> 8); return (c ^ 0xffffffff) >>> 0; };
function chunk(type, data) {
  const len = Buffer.alloc(4); len.writeUInt32BE(data.length);
  const body = Buffer.concat([Buffer.from(type), data]);
  const crc = Buffer.alloc(4); crc.writeUInt32BE(crc32(body));
  return Buffer.concat([len, body, crc]);
}
function png({ w, h, px }) {
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(w, 0); ihdr.writeUInt32BE(h, 4); ihdr[8] = 8; ihdr[9] = 6;
  const raw = Buffer.alloc((w * 4 + 1) * h);
  for (let y = 0; y < h; y++) Buffer.from(px.buffer, y * w * 4, w * 4).copy(raw, y * (w * 4 + 1) + 1);
  return Buffer.concat([Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]), chunk('IHDR', ihdr), chunk('IDAT', deflateSync(raw, { level: 9 })), chunk('IEND', Buffer.alloc(0))]);
}
const save = (name, c) => writeFileSync(new URL(name, OUT), png(c));

const lerp = (a, b, t) => a.map((v, i) => Math.round(v + (b[i] - v) * t));
function gradient(stops, t) {
  for (let i = 1; i < stops.length; i++) {
    if (t <= stops[i][0]) {
      const [p0, c0] = stops[i - 1], [p1, c1] = stops[i];
      return lerp(c0, c1, (t - p0) / (p1 - p0 || 1));
    }
  }
  return stops.at(-1)[1];
}
const rgb = (h, a = 255) => [parseInt(h.slice(1, 3), 16), parseInt(h.slice(3, 5), 16), parseInt(h.slice(5, 7), 16), a];

// ---------- palette ----------
const P = {
  ink: '#0b1630', navy: '#14284a', cobalt: '#1f56a0', ice: '#eaf6ff', frost: '#a9c2dc',
  lime: '#b8ee75', limeDark: '#5f8f2c', amber: '#ffc861', edge: '#142038',
};
const CHROME = [[0, rgb('#f6fbff')], [0.46, rgb('#aebfd2')], [0.5, rgb('#5d7591')], [1, rgb('#c8d6e7')]];
const PRESSED = [[0, rgb('#2a63a3')], [0.55, rgb('#0b2a55')], [1, rgb('#1a4277')]];

// ---------- LCD digits: 10 glyphs, 9×13 each, plus a blank cell (99×13) ----------
function digits() {
  const c = canvas(99, 13);
  const SEG = {
    a: [[2, 0, 5, 2]], g: [[2, 6, 5, 1]], d: [[2, 11, 5, 2]],
    f: [[1, 1, 2, 5]], b: [[6, 1, 2, 5]], e: [[1, 7, 2, 5]], c: [[6, 7, 2, 5]],
  };
  const MAP = ['abcdef', 'bc', 'abged', 'abgcd', 'fgbc', 'afgcd', 'afgedc', 'abc', 'abcdefg', 'abcdfg'];
  for (let n = 0; n < 10; n++) {
    const ox = n * 9;
    for (const [key, rects] of Object.entries(SEG)) {
      const on = MAP[n].includes(key);
      for (const [x, y, w, h] of rects) c.rect(ox + x, y, w, h, on ? P.ice : '#eaf6ff26');
    }
  }
  return c;
}

// ---------- transport buttons: classic 136×36 sheet layout ----------
function buttons() {
  const c = canvas(136, 36);
  const cells = [
    ['prev', 0, 23, 18], ['play', 23, 23, 18], ['pause', 46, 23, 18],
    ['stop', 69, 23, 18], ['next', 92, 22, 18], ['eject', 114, 22, 16],
  ];
  for (const [name, x, w, h] of cells) {
    for (const pressed of [false, true]) {
      const y = pressed ? h : 0;
      bevelButton(c, x, y, w, h, pressed);
      icon(c, name, x, y, w, h, pressed);
    }
  }
  return c;
}

function bevelButton(c, x, y, w, h, pressed) {
  for (let j = 0; j < h; j++) {
    const color = gradient(pressed ? PRESSED : CHROME, j / (h - 1));
    for (let i = 0; i < w; i++) c.set(x + i, y + j, color);
  }
  // Rounded 1px outline, with the corner pixels cut off.
  for (let i = 1; i < w - 1; i++) { c.set(x + i, y, P.edge); c.set(x + i, y + h - 1, P.edge); }
  for (let j = 1; j < h - 1; j++) { c.set(x, y + j, P.edge); c.set(x + w - 1, y + j, P.edge); }
  for (const [cx, cy] of [[0, 0], [w - 1, 0], [0, h - 1], [w - 1, h - 1]]) c.clear(x + cx, y + cy);
  // Inner highlight / shadow.
  for (let i = 2; i < w - 2; i++) c.set(x + i, y + 1, pressed ? '#ffffff30' : '#ffffffc0');
  for (let i = 2; i < w - 2; i++) c.set(x + i, y + h - 2, pressed ? '#00000040' : '#5d759180');
}

function icon(c, name, x, y, w, h, pressed) {
  const fg = pressed ? P.ice : P.ink, glow = pressed ? '#00000060' : '#ffffffa0';
  const cx = x + Math.floor(w / 2), cy = y + Math.floor(h / 2);
  const draw = (pts) => { for (const [i, j] of pts) c.set(i, j + 1, glow); for (const [i, j] of pts) c.set(i, j, fg); };
  const tri = (left, dir, size) => { // dir 1 = pointing right, -1 = left
    const pts = [];
    for (let i = 0; i < size; i++) {
      const span = dir > 0 ? size - 1 - i : i;
      for (let j = -span; j <= span; j++) pts.push([left + i, cy + j]);
    }
    return pts;
  };
  const bar = (bx, by, bw, bh) => { const pts = []; for (let i = 0; i < bw; i++) for (let j = 0; j < bh; j++) pts.push([bx + i, by + j]); return pts; };
  if (name === 'play') draw(tri(cx - 3, 1, 6));
  if (name === 'pause') draw([...bar(cx - 3, cy - 4, 2, 9), ...bar(cx + 1, cy - 4, 2, 9)]);
  if (name === 'stop') draw(bar(cx - 4, cy - 4, 8, 8));
  if (name === 'prev') draw([...bar(cx - 5, cy - 4, 2, 9), ...tri(cx - 3, -1, 5), ...tri(cx + 1, -1, 5)]);
  if (name === 'next') draw([...tri(cx - 5, 1, 5), ...tri(cx - 1, 1, 5), ...bar(cx + 4, cy - 4, 2, 9)]);
  if (name === 'eject') {
    const pts = [];
    for (let j = 0; j < 4; j++) for (let i = -j; i <= j; i++) pts.push([cx + i, cy - 4 + j]);
    draw([...pts, ...bar(cx - 3, cy + 2, 7, 2)]);
  }
}

// ---------- title strip: 275×14, transparent so the chrome gradient shows through ----------
const FONT = {
  B: ['11110', '10001', '10001', '11110', '10001', '10001', '11110'],
  I: ['111', '010', '010', '010', '010', '010', '111'],
  T: ['11111', '00100', '00100', '00100', '00100', '00100', '00100'],
  '.': ['00', '00', '00', '00', '00', '11', '11'],
  C: ['01111', '10000', '10000', '10000', '10000', '10000', '01111'],
  H: ['10001', '10001', '10001', '11111', '10001', '10001', '10001'],
  E: ['11111', '10000', '10000', '11110', '10000', '10000', '11111'],
  R: ['11110', '10001', '10001', '11110', '10100', '10010', '10001'],
};
function titlebar() {
  const c = canvas(275, 14);
  const text = 'BIT.CHEER';
  const textWidth = [...text].reduce((sum, ch) => sum + FONT[ch][0].length + 1, -1);
  const plateW = 4 + 9 + 5 + textWidth + 6 + 3 * 7 + 2 + 4, plateX = Math.floor((275 - plateW) / 2), plateY = 1, plateH = 12;

  // Grooves running out from the plate, fading toward the strip ends.
  for (let x = 0; x < 275; x++) {
    if (x >= plateX - 2 && x < plateX + plateW + 2) continue;
    const dist = x < plateX ? plateX - x : x - (plateX + plateW);
    const fade = Math.max(0, 1 - dist / 95);
    for (const row of [4, 8]) {
      c.set(x, row, [6, 14, 30, Math.round(200 * fade)]);
      c.set(x, row + 1, [196, 214, 236, Math.round(150 * fade)]);
    }
  }

  // Recessed plate.
  for (let j = 0; j < plateH; j++) {
    const color = gradient([[0, rgb('#050c1c')], [0.5, rgb('#0f2244')], [1, rgb('#1b3864')]], j / (plateH - 1));
    for (let i = 1; i < plateW - 1; i++) c.set(plateX + i, plateY + j, color);
  }
  for (let j = 1; j < plateH - 1; j++) { c.set(plateX, plateY + j, '#050c1c'); c.set(plateX + plateW - 1, plateY + j, '#050c1c'); }
  for (let i = 1; i < plateW - 1; i++) c.set(plateX + i, plateY + plateH, '#d7e6f7a0'); // bottom bevel light

  // Lime "b." badge.
  let x = plateX + 4;
  c.rect(x, 3, 9, 9, P.lime);
  c.rect(x, 11, 9, 1, P.limeDark);
  const badge = ['.......', '#......', '#......', '#.##...', '##..#..', '#...#..', '#...#..', '####..#'];
  badge.forEach((row, j) => [...row].forEach((p, i) => { if (p === '#') c.set(x + 1 + i, 3 + j, '#17200d'); }));
  x += 9 + 5;

  // Wordmark.
  for (const ch of text) {
    const glyph = FONT[ch];
    for (let j = 0; j < 7; j++) for (let i = 0; i < glyph[j].length; i++) {
      if (glyph[j][i] !== '1') continue;
      c.set(x + i + 1, 4 + j + 1, '#000000c0');
      c.set(x + i, 4 + j, ch === '.' ? P.lime : j < 3 ? '#ffffff' : P.ice);
    }
    x += glyph[0].length + 1;
  }
  x += 5;

  // Three little window buttons: minimize, shade, close.
  for (const kind of ['min', 'shade', 'close']) {
    for (let j = 0; j < 7; j++) {
      const color = gradient(CHROME, j / 6);
      for (let i = 0; i < 7; i++) c.set(x + i, 3 + j, color);
    }
    for (let i = 0; i < 7; i++) { c.set(x + i, 3, P.edge); c.set(x + i, 9, P.edge); }
    for (let j = 3; j < 10; j++) { c.set(x, j, P.edge); c.set(x + 6, j, P.edge); }
    if (kind === 'min') c.rect(x + 2, 7, 3, 1, P.ink);
    if (kind === 'shade') { c.rect(x + 2, 5, 3, 1, P.ink); c.rect(x + 2, 7, 3, 1, P.ink); }
    if (kind === 'close') for (let k = 0; k < 3; k++) { c.set(x + 2 + k, 5 + k, P.ink); c.set(x + 4 - k, 5 + k, P.ink); }
    x += 8;
  }
  return c;
}

save('numbers.png', digits());
save('cbuttons.png', buttons());
save('titlebar.png', titlebar());
console.log('Millennium Chrome bitmaps written to public/skins/millennium/');
